import {domLab} from './lab-kit.js';
const c=(key,label,min,max,value,step=1)=>({key,label,min,max,value,step});
const base=`.lab-scene{height:180px;max-width:450px;overflow:auto;border:1px solid #d6d4ce;background:#f8f7f3;border-radius:3px;padding:14px;container-type:inline-size}.lab-scene button,.lab-scene input,.lab-scene select{font:inherit;color:inherit;border:1px solid #aaa;border-radius:3px;padding:9px;background:transparent;min-height:40px;max-width:100%}.lab-scene button{cursor:pointer}.lab-scene button:focus-visible,.lab-scene input:focus-visible{outline:2px solid #222;outline-offset:2px}.lab-scene p{margin:8px 0;font-size:12px;line-height:1.6}.lab-scene h3{font-size:23px;letter-spacing:-1px;margin:4px 0}.lab-scene small{font:10px monospace;letter-spacing:.1em}.lab-scene .row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.lab-scene .ink{background:#242424;color:#fff}.lab-scene .notice{padding:10px;background:#e4e2da}.lab-scene .tiny{font-size:10px}.lab-scene [hidden]{display:none!important}.lab-scene dialog{border:1px solid #333;padding:22px;max-width:min(290px,85vw);background:#f8f7f3;color:#222}.lab-scene dialog::backdrop{background:#0008}.lab-scene .popover-box{border:1px solid #333;padding:14px;background:#f8f7f3;color:#222;max-width:220px}.lab-scene .stage-card{border:1px solid #bbb;padding:12px}.lab-scene .dot{display:block;width:28px;height:28px;border-radius:50%;background:#292929}.lab-scene .track{height:50px;position:relative;padding:10px}.lab-scene .strip{display:flex;gap:8px}.lab-scene .strip>i{display:grid;place-items:center;width:50px;height:50px;background:#292929;color:#fff;font-style:normal}.lab-scene .measure{container-type:inline-size;width:100%;max-width:100%;border:1px dashed #aaa;padding:8px}.lab-scene .layout-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.lab-scene .layout-grid>div{padding:8px;background:#e2e0d9}.lab-scene .case-cover{background:radial-gradient(ellipse at 50% 35%,#ddd 0 20%,#333 21% 35%,#b6b3aa 36%);height:68px}.lab-scene .case-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid;padding-bottom:8px;margin-bottom:10px}.lab-scene .case-head b{font-size:18px}.lab-scene .case-layout{display:grid;grid-template-columns:1fr 1fr;gap:14px}@container(max-width:280px){.lab-scene .case-layout{grid-template-columns:1fr}}`;
function setup({root,values:v,kind,on,reduced}){
 const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)],stage=$('.lab-scene'),status=$('.lab-status');let timers=[],animations=[],stopped=false,phase=0,dead=false;
 const say=s=>status.textContent=s,wait=(fn,t)=>{const id=setTimeout(()=>{if(!dead)fn()},t);timers.push(id)},animate=(el,frames,options={})=>{if(reduced||stopped)return null;const a=el.animate(frames,{duration:v.duration||650,fill:'both',easing:'cubic-bezier(.2,.8,.2,1)',...options});animations.push(a);return a};
 const apply=()=>{stage.style.setProperty('--width',v.width+'%');stage.style.setProperty('--scale',v.size);if($('.measure'))$('.measure').style.width=(v.width||100)+'%';};
 let action=()=>{};
 if(kind==='ui-dialog'){const d=$('dialog'),trigger=$('[data-open]');on(trigger,'click',()=>{d.showModal();say('背景の操作を止め、フォーカスをダイアログへ')});on($('[data-close]'),'click',()=>d.close());on(d,'close',()=>{trigger.focus();say('元のボタンへフォーカスを戻しました')});action=()=>{if(d.open)d.close();else trigger.click()};}
 if(kind==='ui-popover'||kind==='ui-tooltip'||kind==='ui-menu'){
  const box=$('.popover-box'),button=$('[data-open]');let open=false;const native=typeof box.showPopover==='function';
  const show=value=>{open=value;button.setAttribute('aria-expanded',String(value));if(native){try{value?box.showPopover():box.hidePopover()}catch{}}else box.hidden=!value;say(native?'Popover API · 外側のクリック／Escapeで閉じます':'この環境では通常の開閉表示で代替します')};
  if(!native){box.removeAttribute('popover');box.hidden=true}on(button,'click',()=>show(!open));on(box,'toggle',e=>{open=e.newState==='open';button.setAttribute('aria-expanded',String(open))});on(stage,'keydown',e=>{if(e.key==='Escape')show(false)});
  if(kind==='ui-tooltip'){on(button,'focus',()=>show(true));on(button,'blur',()=>show(false));on(button,'pointerenter',()=>show(true));on(button,'pointerleave',()=>show(false));}
  for(const b of box.querySelectorAll('button'))on(b,'click',()=>{show(false);say(b.textContent+'を選択');button.focus()});action=()=>show(!open);
 }
 if(kind==='ui-validation'||kind==='case-form'){
  const f=$('form'),input=$('input[type=email]'),msg=$('[data-message]');on(input,'input',()=>{input.removeAttribute('aria-invalid');msg.textContent=''});
  on(f,'submit',e=>{e.preventDefault();if(!input.validity.valid){input.setAttribute('aria-invalid','true');msg.textContent='メールアドレスを確認してください。例 hello@example.com';input.focus();say('入力欄と説明を関連付けています');return}input.setAttribute('aria-invalid','false');msg.textContent='入力を確認しました。この見本は外部に送信しません。';say('✓ 完了');});action=()=>f.requestSubmit();
 }
 if(kind==='ui-submit'){
  const b=$('[data-submit]'),out=$('[data-message]'),mode=$('select');on(b,'click',()=>{if(b.disabled)return;b.disabled=true;b.setAttribute('aria-busy','true');out.textContent='処理中…';say('操作の重複を防止');wait(()=>{b.disabled=false;b.removeAttribute('aria-busy');out.textContent=mode.value==='success'?'✓ 完了しました':'! 接続できませんでした。もう一度試せます。';say(mode.value==='success'?'完了状態':'再試行できる状態')},900)});action=()=>b.click();
 }
 if(kind==='ui-empty'){let items=0;action=()=>{items=items?0:3;$('[data-empty]').hidden=!!items;$('[data-items]').hidden=!items;say(items?'内容がある状態':'次の操作を案内する空の状態')};on($('[data-add]'),'click',action);}
 if(kind==='ui-undo'){const item=$('[data-item]'),undo=$('[data-undo]');on($('[data-delete]'),'click',()=>{item.hidden=true;undo.hidden=false;say('項目を取り除きました。取り消せます。');undo.focus()});on(undo,'click',()=>{item.hidden=false;undo.hidden=true;$('[data-delete]').focus();say('元に戻しました')});action=()=>{item.hidden?undo.click():$('[data-delete]').click()};}
 if(kind==='layout-input'){const pointer=matchMedia('(pointer:coarse)');$('[data-mode]').textContent=pointer.matches?'端末の入力方式 · タッチ中心':'端末の入力方式 · 精密なポインター';action=()=>{stage.classList.toggle('coarse');say(stage.classList.contains('coarse')?'タッチ向けの大きな操作領域':'マウス向けのコンパクトな操作領域')};}
 if(kind==='rhythm-timeline'){action=()=>{animations.forEach(a=>a.cancel());$$('.strip i').forEach((el,i)=>animate(el,[{opacity:0,transform:'translateY(25px)'},{opacity:1,transform:'none'}],{delay:i*v.delay,fill:'both'}));say('位置・透明度・時間差を一つのシーケンスで設計')};}
 if(kind==='rhythm-interrupt'){const dot=$('.dot');action=()=>{const current=getComputedStyle(dot).transform;animations.forEach(a=>a.cancel());phase=1-phase;const target=phase?Math.max(0,stage.clientWidth-85):0;animate(dot,[{transform:current},{transform:`translateX(${target}px)`}],{duration:v.duration});if(reduced||stopped)dot.style.transform=`translateX(${target}px)`;say('連打すると、現在位置から新しい目的地へ向かいます')};}
 if(kind==='rhythm-enter-exit'){const card=$('.stage-card');action=()=>{animations.forEach(a=>a.cancel());phase=1-phase;card.style.opacity=phase?'0':'1';animate(card,phase?[{opacity:1,transform:'none'},{opacity:0,transform:'translateY(-15px)'}]:[{opacity:0,transform:'translateY(25px)'},{opacity:1,transform:'none'}],{duration:phase?v.duration*.55:v.duration});say(phase?'退場は短く、上へ':'登場は少し長く、下から')};}
 if(kind==='transition-native'){const change=()=>{phase=1-phase;stage.classList.toggle('expanded',!!phase);$('[data-title]').textContent=phase?'A closer look.':'An object.'};action=()=>{if(document.startViewTransition&&!reduced&&!stopped){document.startViewTransition(change);say('View Transition API で状態を更新')}else{change();say('通常の切り替えで表示しています')}};}
 if(kind==='scroll-native'){const port=$('.native-scroll'),bar=$('.native-progress'),native=CSS.supports('animation-timeline','scroll()');if(!native){on(port,'scroll',()=>{const p=port.scrollTop/Math.max(1,port.scrollHeight-port.clientHeight);bar.style.transform=`scaleX(${p})`})}say(native?'CSS scroll() でスクロールと進行度を接続':'JavaScriptで進行度を代替表示');action=()=>{port.scrollTop=port.scrollTop>20?0:port.scrollHeight};}
 if(kind==='access-motion'){const card=$('.stage-card');action=()=>{phase=1-phase;card.textContent=phase?'✓ Saved':'Draft';animations.forEach(a=>a.cancel());if($('input[type=checkbox]').checked||reduced){say('動きは使わず、文字と状態の違いで伝えます')}else{animate(card,[{transform:'translateY(20px)',opacity:0},{transform:'none',opacity:1}]);say('動きと文字で状態を伝えます')}};}
 if(kind==='access-feedback'){action=()=>{phase=1-phase;$('[data-message]').textContent=phase?'✓ 保存しました。':'! 入力内容を確認してください。';say('色に加えて、記号と文章でも状態を伝える')};}
 if(kind==='case-product'){const b=$('[data-cart]');on(b,'click',()=>{const n=Number(b.dataset.count||0)+1;b.dataset.count=n;b.textContent=`バッグに追加済み · ${n}`;say('✓ オブジェクトを追加しました');animate($('.case-cover'),[{transform:'scale(.95)'},{transform:'scale(1)'}])});action=()=>b.click();}
 if(kind==='case-editorial'){const port=$('.story-port');on(port,'scroll',()=>{$('[data-progress]').style.width=(port.scrollTop/Math.max(1,port.scrollHeight-port.clientHeight)*100)+'%'});action=()=>{port.scrollTop=port.scrollTop?0:port.scrollHeight};}
 if(kind==='case-gallery'){const hero=$('.case-cover');$$('[data-image]').forEach(b=>on(b,'click',()=>{const next=b.dataset.image;hero.style.background=`linear-gradient(${Number(next)*60}deg,#111,#c7c3b9)`;$$('[data-image]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));say('作品 '+next+' を選択');animate(hero,[{opacity:.2},{opacity:1}])}));action=()=>{$$('[data-image]')[phase++%3].click()};}
 return{update(){apply();if(kind==='layout-fluid')say('枠を縮めて、文字と余白の変化を観察');if(kind==='layout-subgrid')say(CSS.supports('grid-template-columns','subgrid')?'Subgridで内側と外側の列を共有':'非対応環境では独立したGridで表示');},action,setAuto(auto){stopped=!auto;animations.forEach(a=>auto?a.play():a.pause())},destroy(){dead=true;timers.forEach(clearTimeout);animations.forEach(a=>a.cancel());const d=$('dialog');if(d?.open)d.close();for(const p of $$('[popover]')){try{p.hidePopover()}catch{}}}};
}
export const practiceLabs=[];
function add(id,category,name,ja,description,scene,css='',controls=[],extra={}){practiceLabs.push(domLab({id,category,categories:extra.categories||[category],name,ja,description,use:extra.use||'実際の画面で、操作と情報の関係を設計するとき。',tip:extra.tip||'見本のボタンを操作し、変わる場所と、変わらない場所を見比べてください。',tags:[ja,category,...(extra.tags||[])],inputs:extra.inputs||['pointer',...(controls.length?['adjust']:[])],source:extra.source||'https://developer.mozilla.org/en-US/docs/Web/Accessibility',level:extra.level||'applied',targets:extra.targets||['ui'],contexts:extra.contexts||['navigation'],support:extra.support||'標準機能。端末ごとの検証状況は収録マップを参照。',...extra},setup,controls,scene,base+css,{static:true,action:extra.action||'試してみる'}));}
add('ui-dialog','ui','Modal dialog','集中する場所をつくる','dialog要素で背景の操作を止め、閉じると元の操作位置へ戻します。','<button data-open>詳細をひらく ↗</button><dialog aria-label="オブジェクトの詳細"><small>OBJECT / 01</small><h3>A quiet object.</h3><p>背景から一度、視線を切り離す。</p><button data-close>閉じる</button></dialog>','',[],{source:'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/dialog'});
const popCSS='.popover-box{margin:auto}.anchor-button{anchor-name:--trigger}.popover-box{position-anchor:--trigger}@supports(position-area:bottom){.popover-box{position-area:bottom;margin:8px;position-try-fallbacks:flip-block}}';
add('ui-popover','ui','Anchored popover','きっかけの近くで開く','Popover APIとCSS Anchor Positioningで、操作元に結びついた補足を表示します。','<button class="anchor-button" data-open aria-expanded="false">表示オプション</button><div class="popover-box" popover><b>View options</b><p>外側をタップすると閉じます。</p></div>',popCSS,[],{source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Anchor_positioning',support:'Popover非対応時は通常表示。Anchor Positioning非対応時は中央配置。'});
add('ui-tooltip','ui','Tooltip with focus','触れる・選ぶで補足を読む','ポインターとキーボードのフォーカスのどちらでも補足を表示します。','<button class="anchor-button" data-open aria-describedby="help-tip">ⓘ 作品情報</button><div id="help-tip" class="popover-box" popover="manual" role="tooltip">作者・制作年・素材を確認できます。</div>',popCSS);
add('ui-menu','ui','Disclosure navigation','メニューを開いて選ぶ','ボタンでナビゲーションを開き、選択したら閉じます。','<button class="anchor-button" data-open aria-expanded="false">Explore ＋</button><nav class="popover-box" popover aria-label="見本のナビゲーション"><div class="row"><button>Objects</button><button>Stories</button><button>About</button></div></nav>',popCSS);
const form='<form novalidate><label>メールアドレス<input type="email" required placeholder="hello@example.com" aria-describedby="form-message" autocomplete="off"></label><button class="ink" type="submit">確認する →</button><p id="form-message" data-message role="status"></p></form>';
add('ui-validation','ui','Inline validation','直す場所がすぐわかる','入力欄の近くに理由を表示し、誤りのある欄へフォーカスを移します。',form,'form{display:grid;gap:8px}form label{display:grid;gap:6px;font-size:12px}');
add('ui-submit','ui','Async submit states','待つ・完了・再試行を伝える','処理中は重複操作を防ぎ、成功と失敗を文字で伝えます。通信を模した900msの見本です。','<div class="row"><select aria-label="処理結果"><option value="success">成功させる</option><option value="error">失敗させる</option></select><button class="ink" data-submit>送信を試す</button></div><p data-message role="status">準備ができています。</p>');
add('ui-empty','ui','Empty state','空の場所から次へ進める','内容がない理由と、次にできる操作を同じ場所に置きます。','<div data-empty><small>YOUR COLLECTION</small><h3>まだ、まっさら。</h3><button data-add>最初の作品を加える ＋</button></div><div data-items hidden class="strip"><i>01</i><i>02</i><i>03</i></div>');
add('ui-undo','ui','Undo feedback','取り消せる安心感をつくる','削除した項目を保持し、取り消し操作で同じ状態へ戻します。','<div class="row" data-item><b>Object 01</b><button data-delete>コレクションから外す</button></div><button data-undo hidden>取り消して元に戻す ↶</button>');
add('layout-fluid','layout','Fluid type & spacing','文字も余白も、連続して変わる','clampとコンテナ単位で、枠の幅に合わせて文字と余白を連続的に変えます。','<div class="measure"><div class="fluid"><small>RESPONSIVE</small><h3>Room to breathe.</h3><p>文字と余白の関係を保つ。</p></div></div>','.fluid{padding:clamp(4px,4cqi,20px)}.fluid h3{font-size:clamp(18px,9cqi,38px)!important}',[c('width','枠の幅 %',40,100,100)],{categories:['layout','type'],targets:['text','layout'],contexts:['responsive'],source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/clamp'});
add('layout-art-direction','layout','Responsive art direction','幅に応じて、構図を変える','同じ景色でも、小さい枠では主役を大きく切り取り、大きい枠では周囲を見せます。','<div class="measure"><div class="art-crop"><span>●</span><b>LANDSCAPE</b></div></div>','.art-crop{height:100px;background:linear-gradient(160deg,#ccc 50%,#555 51%);position:relative;overflow:hidden}.art-crop span{position:absolute;left:20%;top:5%;font-size:65px}.art-crop b{position:absolute;right:8px;bottom:8px;font-size:12px}@container(max-width:220px){.art-crop span{left:30%;font-size:120px;top:-35%}.art-crop b{font-size:9px}}',[c('width','枠の幅 %',40,100,100)],{categories:['layout','image'],targets:['image'],contexts:['responsive'],source:'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/picture',tip:'これは構図の違いをCSSで再現する教材です。実画像ではpicture要素で縦横の素材を切り替えられます。'});
add('layout-subgrid','layout','Subgrid alignment','部品をまたいで列を揃える','内側のGridが外側の列を引き継ぎ、見出しと値の基準線を共有します。','<div class="subgrid"><b>ITEM</b><b>SIZE</b><b>YEAR</b><div><span>Object</span><span>Small</span><span>2026</span></div><div><span>Long title</span><span>Large</span><span>2025</span></div></div>','.subgrid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;font-size:11px}.subgrid>div{grid-column:1/-1;display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;border-top:1px solid #bbb;padding-top:12px}@supports(grid-template-columns:subgrid){.subgrid>div{grid-template-columns:subgrid}}',[],{source:'https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_grid_layout/Subgrid',contexts:['responsive'],targets:['layout']});
add('layout-input','interaction','Input-adaptive controls','指とマウスで、触れる幅を変える','入力機器の精度に合わせて操作領域を変える考え方を、切り替えて比較します。','<p data-mode></p><div class="row"><button>−</button><span>01</span><button>＋</button></div>','.lab-scene .row button{min-width:30px;min-height:30px}.lab-scene.coarse .row button{min-width:52px;min-height:52px}',[],{categories:['interaction','layout'],contexts:['responsive'],action:'タッチ／マウスの例',source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/At-rules/@media/pointer'});
add('rhythm-timeline','rhythm','Coordinated timeline','複数の動きを、一つの流れにする','各要素の開始時刻をずらし、共通の長さと緩急で順序をつくります。','<div class="strip"><i>01</i><i>02</i><i>03</i><i>04</i></div>','',[c('delay','開始の間隔 ms',0,500,150,25),c('duration','動く時間 ms',200,1500,700,50)],{categories:['rhythm','motion'],source:'https://developer.mozilla.org/en-US/docs/Web/API/Web_Animations_API'});
add('rhythm-interrupt','rhythm','Interruptible motion','動いている途中でも、自然に戻る','再操作の瞬間の見た目を読み取り、その位置から次の目的地へ補間します。','<div class="track"><span class="dot"></span></div>','',[c('duration','移動時間 ms',200,2000,1200,100)],{categories:['rhythm','interaction'],action:'左右へ移動 · 連打して比較',source:'https://developer.mozilla.org/en-US/docs/Web/API/Element/animate'});
add('rhythm-enter-exit','rhythm','Enter & exit choreography','登場と退場の役割を変える','登場は認識しやすく、退場は次へ進みやすい長さに分けます。','<div class="stage-card"><h3>Hello, again.</h3><p>消える。戻ってくる。</p></div>','',[c('duration','登場の時間 ms',300,1600,800,100)],{categories:['rhythm','transition'],source:'https://developer.mozilla.org/en-US/docs/Web/API/Element/animate'});
add('transition-native','transition','Native view transition','ブラウザが画面の変化をつなぐ','View Transition APIで、状態変更前後の画面を連続して見せます。非対応環境は通常の切り替えです。','<div class="case-cover"></div><h3 data-title>An object.</h3>','.expanded .case-cover{height:110px}.expanded h3{font-size:15px}',[],{source:'https://developer.mozilla.org/en-US/docs/Web/API/View_Transition_API',support:'document.startViewTransitionを検出。非対応時は即時切り替え。'});
add('scroll-native','scroll','CSS scroll timeline','スクロールを、CSSの時間にする','scroll()タイムラインで、スクロール量をアニメーションの進行度に接続します。','<div class="native-scroll" tabindex="0" aria-label="見本をスクロール"><div class="native-progress"></div><h3>Keep going.</h3><p>01 — はじまり</p><div style="height:130px"></div><p>02 — 途中の景色</p><div style="height:130px"></div><p>03 — たどり着く</p></div>','.native-scroll{height:145px;overflow:auto;scroll-timeline:--reading block}.native-progress{height:5px;background:#222;position:sticky;top:0;transform-origin:left;transform:scaleX(0)}@supports(animation-timeline:scroll()){.native-progress{animation:reading-progress linear both;animation-timeline:--reading}}@keyframes reading-progress{to{transform:scaleX(1)}}',[],{inputs:['scroll','pointer'],source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/animation-timeline',support:'CSSの対応を検出し、非対応時はscrollイベントで代替。'});
add('access-motion','interaction','Reduced-motion alternative','動きを減らしても、意味を残す','同じ保存操作を、動きありと状態表示だけの二通りで比較します。','<label class="tiny"><input type="checkbox" checked> 動きを抑える</label><div class="stage-card">Draft</div>','',[],{tags:['アクセシビリティ','reduced motion'],contexts:['accessibility'],action:'状態を切り替える'});
add('access-feedback','interaction','Multimodal feedback','色だけに、意味を預けない','記号・文章・読み上げ通知を重ね、状態を複数の方法で伝えます。','<h3>Every signal counts.</h3><p data-message role="status">✓ 保存しました。</p>','',[],{tags:['アクセシビリティ','通知'],contexts:['accessibility']});
add('case-product','style','Object shop — composed example','商品を知り、選び、加える','タイポグラフィ、構図、操作の反応を一つの商品紹介に組み合わせます。','<div class="case-head"><b>OBJECT / 01</b><small>EDITION</small></div><div class="case-layout"><div class="case-cover"></div><div><h3>A quiet object.</h3><p>日々に、小さな余白を。</p><button data-cart class="ink">バッグに加える ＋</button></div></div>','',[],{level:'composition',categories:['style','layout','interaction'],contexts:['commerce'],related:['layout-fluid','rhythm-interrupt','ui-submit'],tip:'構図→文字の強弱→操作→完了の手応えを、一連の流れとして観察してください。販売や決済は行いません。'});
add('case-editorial','style','Reading room — composed example','読む進度と、余白を組み合わせる','文字組み、段階的な情報、読了の進行度を一つの記事体験にまとめます。','<div class="story-port" tabindex="0" aria-label="記事をスクロール"><div class="story-progress"><i data-progress></i></div><small>FIELD NOTES / 01</small><h3>余白を、読む。</h3><p>ひとつの形に目が留まる。<br>その隣に、何も置かない。</p><div style="height:90px"></div><h3>目が、休まる。</h3><p>情報の間隔も、表現の一部です。</p><div style="height:90px"></div><p>次の景色へ。</p></div>','.story-port{height:145px;overflow:auto}.story-progress{position:sticky;top:0;height:3px;background:#ddd}.story-progress i{display:block;height:3px;background:#222;width:0}',[],{level:'composition',categories:['style','type','scroll'],contexts:['editorial'],inputs:['scroll','pointer'],related:['type-leading','layout-spacing','scroll-native']});
add('case-gallery','style','Small gallery — composed example','選ぶ動作で、作品の見え方が変わる','作品一覧、選択状態、フェードを一つの小さなギャラリーに組み合わせます。','<div class="case-head"><b>SMALL GALLERY</b><small>03 WORKS</small></div><div class="case-cover"></div><div class="row"><button data-image="1" aria-pressed="true">01</button><button data-image="2" aria-pressed="false">02</button><button data-image="3" aria-pressed="false">03</button></div>','',[],{level:'composition',categories:['style','image','transition'],contexts:['portfolio'],related:['transition-crossfade','ui-segmented','layout-alignment']});
add('case-form','style','Thoughtful form — composed example','迷わず入力して、完了を知る','見出し、入力の説明、検証、完了通知を一つのフォームにまとめます。','<small>STAY CURIOUS</small>'+form,'form{display:grid;gap:6px}form label{font-size:11px;display:grid;gap:5px}',[],{level:'composition',categories:['style','ui','interaction'],contexts:['forms'],related:['ui-validation','ui-submit','access-feedback']});
